ON DUPLICATE KEY UPDATE stopSequence = VALUES(stopSequence), arrivalTime = VALUES(arrivalTime), departureTime = VALUES(departureTime), arrivalDayOffset = VALUES(arrivalDayOffset), departureDayOffset = VALUES(departureDayOffset);

ON DUPLICATE KEY UPDATE distanceKm = VALUES(distanceKm);


-- Additional corridor and intercity services (sample timetable and route distances).


-- Additional major regional stations and sample services.
ON DUPLICATE KEY UPDATE name = VALUES(name), city = VALUES(city), state = VALUES(state);

UPDATE train SET trainNumber = LPAD(id, 3, '0') WHERE id BETWEEN 1 AND 56;

ON DUPLICATE KEY UPDATE trainNumber = VALUES(trainNumber), name = VALUES(name), trainType = VALUES(trainType);

